                year: '2016-2017',
                details: '2016년 12월 준공, 2017년 4월 개장'
            }
        ];

        let scene, camera, renderer, controls;
        let currentStage = 0;
        let autoRotate = false;
        let towerModel = null;

        function initThreeJS() {
            const container = document.getElementById('canvasContainer');

            // Scene
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x0a0a0a);
            scene.fog = new THREE.Fog(0x0a0a0a, 2000, 3000);

            // Camera
            camera = new THREE.PerspectiveCamera(
                75,
                container.clientWidth / container.clientHeight,
                0.1,
                5000
            );
            camera.position.set(300, 300, 300);
            camera.lookAt(0, 0, 0);

            // Renderer
            renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
            renderer.setSize(container.clientWidth, container.clientHeight);
            renderer.setPixelRatio(window.devicePixelRatio);
            renderer.shadowMap.enabled = true;
            renderer.shadowMap.type = THREE.PCFShadowShadowMap;
            container.appendChild(renderer.domElement);

            // Controls
            controls = new THREE.OrbitControls(camera, renderer.domElement);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.autoRotate = false;
            controls.autoRotateSpeed = 2;
            controls.minDistance = 200;
            controls.maxDistance = 1500;

            // Lighting
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(500, 800, 500);
            directionalLight.castShadow = true;
            directionalLight.shadow.mapSize.width = 2048;
            directionalLight.shadow.mapSize.height = 2048;
            directionalLight.shadow.camera.far = 2000;
            directionalLight.shadow.camera.left = -1000;
            directionalLight.shadow.camera.right = 1000;
            directionalLight.shadow.camera.top = 1000;
            directionalLight.shadow.camera.bottom = -1000;
            scene.add(directionalLight);

            // Ground
            const groundGeometry = new THREE.PlaneGeometry(2000, 2000);
            const groundMaterial = new THREE.MeshStandardMaterial({
                color: 0x1a1a2e,
                roughness: 0.8,
                metalness: 0.1
            });
            const ground = new THREE.Mesh(groundGeometry, groundMaterial);
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            scene.add(ground);

            // Grid helper
            const gridHelper = new THREE.GridHelper(1000, 20, 0x444444, 0x222222);
            gridHelper.position.y = 0.1;
            scene.add(gridHelper);

            // Axes helper (subtle)
            const axesHelper = new THREE.AxesHelper(200);
            scene.add(axesHelper);

            // Event listeners
            window.addEventListener('resize', onWindowResize);
            document.addEventListener('keydown', onKeyDown);

            // Initial model
            createTowerModel(0);
            animate();
        }

        function createTowerModel(stage) {
            // Remove old model
            if (towerModel) {
                scene.remove(towerModel);
            }

            towerModel = new THREE.Group();

            const stageConfigs = [
                { name: '개념 설계', baseRadius: 92, topRadius: 92, height: 555, segments: 8, color: 0xff6b35, opacity: 0.6 },
                { name: '기본 설계', baseRadius: 92, topRadius: 65, height: 555, segments: 16, color: 0xff8c42, opacity: 0.7 },
                { name: '실시 설계', baseRadius: 92, topRadius: 50, height: 555, segments: 24, color: 0xffa500, opacity: 0.8 },
                { name: '시공 준비', baseRadius: 92, topRadius: 35, height: 555, segments: 32, color: 0xffb84d, opacity: 0.85 },
                { name: '완성', baseRadius: 92, topRadius: 35, height: 555, segments: 64, color: 0xff6b35, opacity: 0.9 }
            ];

            const config = stageConfigs[stage];

            // Create tower geometry with taper
            const geometry = new THREE.LatheGeometry(
                createTowerProfile(config.baseRadius, config.topRadius, config.height),
                config.segments
            );

            const material = new THREE.MeshStandardMaterial({
                color: config.color,
                metalness: 0.3,
                roughness: 0.4,
                emissive: config.color,
                emissiveIntensity: 0.1
            });

            const tower = new THREE.Mesh(geometry, material);
            tower.castShadow = true;
            tower.receiveShadow = true;
            tower.scale.set(1, 1, 1);
            towerModel.add(tower);

            // Add floors visualization for later stages
            if (stage >= 2) {
                addFloorVisualization(towerModel, config.baseRadius, config.topRadius, config.height);
            }

            // Add base platform
            const baseGeometry = new THREE.CylinderGeometry(config.baseRadius + 10, config.baseRadius + 15, 20, 32);
            const baseMaterial = new THREE.MeshStandardMaterial({
                color: 0x333333,
                metalness: 0.5,
                roughness: 0.5
            });
            const base = new THREE.Mesh(baseGeometry, baseMaterial);
            base.position.y = -10;
            base.castShadow = true;
            base.receiveShadow = true;
            towerModel.add(base);

            scene.add(towerModel);
        }

        function createTowerProfile(baseRadius, topRadius, height) {
            const points = [];
            const steps = 64;

            for (let i = 0; i <= steps; i++) {
                const t = i / steps;
                // Smooth curve using ease-in-out
                const easeT = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
                const radius = baseRadius + (topRadius - baseRadius) * easeT;
                const y = (t - 0.5) * height;
                points.push(new THREE.Vector2(radius, y));
            }

            return points;
        }

        function addFloorVisualization(group, baseRadius, topRadius, height) {
            const floorCount = 20; // Show 20 representative floors
            const floorMaterial = new THREE.MeshStandardMaterial({
                color: 0x444444,
                metalness: 0.6,
                roughness: 0.3,
                emissive: 0x222222
            });

            for (let i = 0; i < floorCount; i++) {
                const t = i / (floorCount - 1);
                const easeT = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
                const radius = baseRadius + (topRadius - baseRadius) * easeT;
                const y = (t - 0.5) * height;

                const floorGeometry = new THREE.CylinderGeometry(radius - 2, radius - 2, 2, 32);
                const floor = new THREE.Mesh(floorGeometry, floorMaterial);
                floor.position.y = y;
                floor.castShadow = true;
                floor.receiveShadow = true;
